function test_H01_pricingBoundsBypass_roundingDivergence() public {
    // Setup: token pair with tight pricing bounds (maxSqrtPriceX96 = targetPrice + 1)
    // Action 1: compute amountOut = calculateFixedInput(orderAmount, sqrtPriceX96)
    //           where sqrtPriceX96 is just below maxSqrtPriceX96
    // Action 2: reconstruct price = computeRatioX96(amountOut, orderAmount)
    // Assert: reconstructedPrice != sqrtPriceX96 due to rounding
    //         Specifically check if reconstructedPrice < maxSqrtPriceX96
    //         while sqrtPriceX96 >= maxSqrtPriceX96 (bounds bypass)
    uint160 sqrtPriceX96 = 79228162514264337593543950336; // ~1.0 in Q96
    uint256 orderAmount = 1e18;
    uint256 amountOut = FullMath.mulDivRoundingUp(
        FullMath.mulDivRoundingUp(orderAmount, sqrtPriceX96, Q96),
        sqrtPriceX96, Q96);
    uint160 reconstructed = SqrtPriceCalculator.computeRatioX96(amountOut, orderAmount);
    // If these differ, bounds enforcement is inconsistent
    assert(reconstructed == sqrtPriceX96); // Expected to fail for some inputs
}

function test_H02_roundingAccumulation_multipleSmallFills() public {
    // Setup: Create 1000 orders of 1 wei each at a price where rounding matters
    uint160 sqrtPriceX96 = 79228162514264337593543950337; // slightly above 1.0
    uint256 numOrders = 1000;
    uint256 singleFillOutput = FullMath.mulDivRoundingUp(
        FullMath.mulDivRoundingUp(1, sqrtPriceX96, Q96), sqrtPriceX96, Q96);
    uint256 batchFillOutput = FullMath.mulDivRoundingUp(
        FullMath.mulDivRoundingUp(numOrders, sqrtPriceX96, Q96), sqrtPriceX96, Q96);
    uint256 accumulatedOutput = singleFillOutput * numOrders;
    // Assert: accumulated > batch shows rounding surplus
    assert(accumulatedOutput > batchFillOutput); // surplus extracted from executor
    vm.log_uint(accumulatedOutput - batchFillOutput); // measure the leakage
}

function test_H03_tstorish_staleValue_afterActivation() public {
    // Setup: Deploy AMMStandardHook on chain without tstore support
    //        (uses sstore fallback)
    // Action 1: Execute a direct swap (beforeSwap stores amount=1e18 via sstore)
    //           Swap completes. afterSwap reads the value. But sstore slot NOT cleared.
    // Action 2: Call __activateTstore() -- copies sload(SLOT) -> tstore(SLOT)
    //           The stale 1e18 is now in transient storage
    // Action 3: Execute another direct swap with amount=1e6
    //           beforeSwap writes 1e6 to tstore (correct)
    //           afterSwap reads 1e6 from tload (correct -- overwritten)
    // KEY: The vulnerability window is if afterSwap runs WITHOUT beforeSwap
    //      (e.g., hook flags changed between activation and swap)
    //      Then afterSwap reads the stale 1e18 from the activation copy
    vm.store(address(hook), bytes32(uint256(0xFFFFFFFFFFFFFFFF)), bytes32(uint256(1e18)));
    hook.__activateTstore();
    uint256 staleValue = vm.load(address(hook), bytes32(uint256(0xFFFFFFFFFFFFFFFF)));
    assert(staleValue == 1e18); // stale value persists in tstore
}

function test_H04_maliciousCLOBHook_validateExecutor() public {
    // Setup: Deploy a malicious CLOBHook that performs state reads during validateExecutor
    // Action 1: Create orderbook with malicious hook via initializeOrderBookKey
    // Action 2: Open orders in this orderbook
    // Action 3: Trigger AMM swap that fills from this orderbook
    // Assert: Check if the malicious hook can observe or manipulate state
    //         during the validateExecutor callback before orders are filled
    address maliciousHook = address(new MaliciousHook());
    bytes32 groupKey = handler.generateGroupKey(maliciousHook, 1, 0);
    handler.initializeOrderBookKey(tokenIn, tokenOut, maliciousHook, 1, 0);
    // Verify hook is called before fillOrder
    vm.expectCall(maliciousHook, abi.encodeWithSelector(ICLOBHook.validateExecutor.selector));
}

function test_H05_validateHandlerOrder_invertedPriceBounds() public {
    // Setup: tokenA (address 0x1) = tokenIn, tokenB (address 0x2) = tokenOut
    //        tokenA < tokenB, so tokenA = token0, tokenB = token1
    //        Set pricing bounds on tokenA: minSqrtPriceX96 = P_low, maxSqrtPriceX96 = P_high
    // Action: CLOB calls validateHandlerOrder with hookForTokenIn=true
    //         amountIn = orderAmount (tokenA), amountOut = calculated (tokenB)
    //         amount0 = amountIn (tokenA), amount1 = amountOut (tokenB) [because tokenIn < tokenOut]
    //         sqrtPriceX96 = computeRatioX96(amountOut, amountIn) = sqrt(tokenB_amount/tokenA_amount)
    //         This matches the AMM's sqrt(token1/token0) convention -- CORRECT
    //
    // Now flip: tokenB = tokenIn, tokenA = tokenOut (reverse CLOB order)
    //         hookForTokenIn=true for tokenB's hook
    //         token = tokenB, pairedToken = tokenA
    //         bounds = _pricingBounds[tokenB][tokenA]
    //         amount0 = amountOut (tokenA), amount1 = amountIn (tokenB) [because tokenA < tokenB]
    //         sqrtPriceX96 = computeRatioX96(amountIn, amountOut) = sqrt(tokenB_amount/tokenA_amount)
    //         Bounds for tokenB vs tokenA: are these in the same convention?
    //
    // Assert: Compare bounds check result for forward vs reverse order
    vm.assertTrue(false, 'Trace the price convention for reverse orders');
}

function test_H06_priceMismatch_AMMvsCLOB() public {
    // Setup: Create CLOB orderbook at MIN_SQRT_RATIO price
    //        Create AMM pool with different pricing (e.g., dynamic pool)
    // Action: Execute swap through AMM that triggers CLOB handler fill
    //         AMM computes amountOut based on pool math
    //         CLOB computes stepOutput based on calculateFixedInput at order price
    // Assert: The difference between AMM's amountOut and sum(stepOutputs)
    //         goes to fillOutputRemaining -> refund to executor
    //         But: what if the CLOB's total stepOutput > AMM's amountOut?
    //         This triggers InsufficientOutputToFill revert (line 229)
    //         Meaning: CLOB orders at prices ABOVE pool price cannot be filled
    //         This is by-design, but check: what about orders at prices BELOW pool price?
    //         The executor gets the surplus as refund -- is this MEV-extractable?
    uint256 fillOutputRemaining = amountOut; // from AMM
    uint256 totalCLOBOutput = 0;
    for (uint i = 0; i < numOrders; i++) {
        totalCLOBOutput += calculateFixedInput(orderInput[i], orderPrice[i]);
    }
    assert(totalCLOBOutput <= fillOutputRemaining); // surplus goes to executor
}

function test_H07_closeOrder_partialFill_amountAccuracy() public {
    // Setup: Create order with inputAmount = 1000
    //        Partially fill it (fill 600, leaving inputAmountRemaining = 400)
    // Action: Close the partially-filled current order
    // Assert: unfilledInputAmount == 400 (from inputAmountRemaining, not inputAmount)
    //         makerTokenBalance credited with exactly 400
    //         Next order in bucket has correct inputAmountRemaining
    handler.openOrder(tokenIn, tokenOut, price, 1000, groupKey, 0, hookData);
    // Partially fill via ammHandleTransfer with inputAmount=600
    vm.prank(AMM);
    handler.ammHandleTransfer(executor, swapOrder, 600, amountOut, fee, feeOnTop, fillData);
    // Now close the partially-filled order
    uint256 balBefore = handler.makerTokenBalance(tokenIn, maker);
    handler.closeOrder(tokenIn, tokenOut, price, orderNonce, groupKey);
    uint256 balAfter = handler.makerTokenBalance(tokenIn, maker);
    assertEq(balAfter - balBefore, 400, 'Should credit unfilled portion only');
}

function test_H08_directSwap_noBoundsCheck_beforeOnly() public {
    // Setup: Configure token with beforeSwap=ON, afterSwap=OFF
    //        Set tight pricing bounds
    // Action: Execute a direct swap (poolId == bytes32(0))
    //        beforeSwap stores amount but doesn't check bounds
    //        afterSwap is NOT called (flag not set)
    // Assert: Swap succeeds even though price is outside bounds
    //         because _validatePricingBounds only validates in afterSwap path
    //         for direct swaps (returns early in beforeSwap path, line 840)
    vm.prank(registry);
    hook.registryUpdateTokenSettings(token, settings); // beforeSwap ON, afterSwap OFF
    vm.prank(registry);
    hook.registryUpdatePricingBounds(token, pairTokens, minPrices, maxPrices);
    // Direct swap at a price outside bounds should succeed
    vm.prank(AMM);
    uint256 fee = hook.beforeSwap(context, swapParams, hookData);
    // afterSwap never called - bounds never checked
    assert(fee > 0); // fee was charged but bounds not enforced
}

function test_H09_settingsCacheRace_boundsRemoval() public {
    // Setup: Token with pricing bounds set, validateHandlerOrder enforces them
    // Action: In same block:
    //   1. Registry updates pricing bounds to unset (registryUpdatePricingBounds with 0,0)
    //   2. Attacker opens CLOB order at extreme price
    //   3. _enforceTokenHooks calls validateHandlerOrder which now sees no bounds
    // Assert: Order is created at extreme price that should have been rejected
    vm.prank(registry);
    hook.registryUpdatePricingBounds(token, pairTokens, zeros, zeros); // unset bounds
    // In same block, open order at extreme price
    handler.openOrder(tokenIn, tokenOut, MAX_SQRT_RATIO, orderAmount, groupKey, 0, hookData);
    // Order succeeds because validateHandlerOrder sees no bounds
}

function test_H10_maliciousTokenHook_openOrderDOS() public {
    // Setup: Token whose tokenHook points to a contract that always reverts
    //        on validateHandlerOrder, but only for certain callers
    // Action: Attacker deploys token with malicious hook that selectively reverts
    //         Users try to open CLOB orders for this token
    // Assert: All CLOB orders for this token are permanently blocked (DoS)
    //         even though the token owner could trade on AMM pools
    address maliciousHook = address(new SelectiveRevertHook());
    // Set token settings in AMM to use maliciousHook with HANDLER_ORDER_VALIDATE flag
    vm.prank(admin);
    amm.setTokenSettings(tokenIn, TokenSettings(0, HANDLER_ORDER_VALIDATE_FLAG, maliciousHook));
    // Try to open CLOB order -- should revert
    vm.expectRevert();
    handler.openOrder(tokenIn, tokenOut, price, amount, groupKey, 0, hookData);
}
